/** Resolve a heliumsolar path or basename to Storebox CDN URL. */
export function storeboxUrl(pathOrName: string): string | undefined {
  const base = pathOrName.split("/").pop() ?? pathOrName;
  if (STOREBOX_MEDIA[base]) return STOREBOX_MEDIA[base];
  const sanitized = base
    .replace(/&/g, "-")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");
  return STOREBOX_MEDIA[sanitized];
}
